// Demo: Digital Thermal Sensors — PID fan response to a heat spike
var temp=45,target=75,kp=2.0,fan=30;
console.log('technique: Digital Thermal Sensors');
for(var t=0;t<10;t++){temp+=t<4?8:-3;var err=temp-target;fan=Math.max(20,Math.min(100,fan+kp*err/10));console.log('t='+t+' temp='+temp+'C fan='+Math.round(fan)+'%');}
console.log('fan ramps with temperature, then settles');

