// Demo: RAPL Power Capping — power capping under a 28W budget
var budget=28,pkgs=[];for(var i=0;i<16;i++){pkgs.push(40+((i*37+3)%80));}
var over=pkgs.filter(function(p){return p>budget;}).length;
console.log('technique: RAPL Power Capping');console.log('samples: '+pkgs.length+', over '+budget+'W budget: '+over);
console.log(over>0?'action: cap frequency via RAPL until under budget':'within budget — no throttling');

