// Demo: Workload Migration — workload migration away from a hotspot
var cores=[];for(var i=0;i<8;i++){cores.push(50+((i*29+5)%45));}
var hot=cores.indexOf(Math.max.apply(null,cores));
console.log('technique: Workload Migration');console.log('core temps: '+cores.join(', '));
console.log('hotspot: core '+hot+' at '+cores[hot]+'C — migrate its workload to the coolest core');

